CREATE TABLE IF NOT EXISTS accounts(id INTEGER PRIMARY KEY, name TEXT NOT NULL, share TEXT NOT NULL, loss_sharing INTEGER NOT NULL DEFAULT 0, marketplace TEXT NOT NULL DEFAULT 'EBAY_GB', connected INTEGER NOT NULL DEFAULT 0, token BLOB, refresh_token BLOB, token_expires TEXT, sync_at TEXT, coverage TEXT, error TEXT, cursor TEXT);
CREATE TABLE IF NOT EXISTS share_history(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), percent TEXT NOT NULL, loss_sharing INTEGER NOT NULL, effective_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS orders(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), order_id TEXT NOT NULL, created_at TEXT, modified_at TEXT, currency TEXT, proceeds TEXT, tax TEXT, refunds TEXT, fees TEXT, source_json TEXT NOT NULL, status TEXT, UNIQUE(account_id,order_id));
CREATE TABLE IF NOT EXISTS costs(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), order_id TEXT, sku TEXT, kind TEXT NOT NULL, amount TEXT NOT NULL, currency TEXT NOT NULL, note TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sku_costs(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), sku TEXT NOT NULL, product_cost TEXT NOT NULL DEFAULT '0', fulfilment_cost TEXT NOT NULL DEFAULT '0', currency TEXT NOT NULL, UNIQUE(account_id,sku));
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), transaction_id TEXT NOT NULL, order_id TEXT, type TEXT, amount TEXT, currency TEXT, source_json TEXT NOT NULL, UNIQUE(account_id,transaction_id));
CREATE TABLE IF NOT EXISTS listings(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), sku TEXT, offer_id TEXT, title TEXT, quantity INTEGER, status TEXT, source_json TEXT, UNIQUE(account_id,offer_id));
CREATE TABLE IF NOT EXISTS metrics(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), day TEXT, payload TEXT);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), order_id TEXT, event TEXT NOT NULL, source_json TEXT, created_at TEXT NOT NULL);
